import{_ as a}from"./chunks/daily-2026-08-22-agent-rail-decision-boundary-figure-1.baLn4Zoy.js";import{_ as i,C as n,o,c as s,E as r,a2 as c}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"How Can an Agent Team Work Autonomously? The Rail as a Service for Dispatch, Recovery, and Judgment","description":"","frontmatter":{"title":"How Can an Agent Team Work Autonomously? The Rail as a Service for Dispatch, Recovery, and Judgment","date":"2026-08-22","column":"digital-employee","category":"daily","article_type":"engineering-judgment","edition":"research-center","research_question":"How can an agent team work autonomously within authorized tasks, and which coordination services should a rail provide without deciding for agents, PMs, or ADMIN?","summary":"Agents should advance work autonomously within explicit responsibilities. The rail supplies dispatch, facts, audit, and technical recovery, while limiting hard denial to a frozen negative list rather than becoming an unauthorized manager.","item_id":"MANUAL-20260822-AGENT-RAIL-BOUNDARY","lifecycle":"Published","cover":"/assets/covers/daily-2026-08-22-agent-rail-decision-boundary-cover.png","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"sources":["research/manual-runs/2026-08-22-codeflowmu-rail-state-series-round1/02-source-register.md","research/manual-runs/2026-08-22-codeflowmu-rail-state-series-round1/02-fact-claim-matrices.md"]},"headers":[],"relativePath":"en/digital-employee/2026-08-22-agent-rail-decision-boundary.md","filePath":"en/digital-employee/2026-08-22-agent-rail-decision-boundary.md","lastUpdated":1787553126000}'),l={name:"en/digital-employee/2026-08-22-agent-rail-decision-boundary.md"};function d(h,e,p,u,m,g){const t=n("ArticleCover");return o(),s("div",null,[r(t,{image:"/assets/covers/daily-2026-08-22-agent-rail-decision-boundary-cover.png",kicker:"Digital Employee · Project Research",title:"How Can an Agent Team Work Autonomously? The Rail as a Service for Dispatch, Recovery, and Judgment",summary:"Agents advance autonomously within explicit authority; the rail serves dispatch, facts, and technical recovery. Scope, acceptance, rework, and final conclusions remain with an authorized agent, PM, or ADMIN.",version:"MANUAL-20260822-AGENT-RAIL-BOUNDARY",status:"Editorial & Visual PASS · 2026-08-23",languageHref:"/zh/digital-employee/2026-08-22-agent-rail-decision-boundary",languageLabel:"中文"}),e[0]||(e[0]=c('<h1 id="how-can-an-agent-team-work-autonomously-the-rail-as-a-service-for-dispatch-recovery-and-judgment" tabindex="-1">How Can an Agent Team Work Autonomously? The Rail as a Service for Dispatch, Recovery, and Judgment <a class="header-anchor" href="#how-can-an-agent-team-work-autonomously-the-rail-as-a-service-for-dispatch-recovery-and-judgment" aria-label="Permalink to &quot;How Can an Agent Team Work Autonomously? The Rail as a Service for Dispatch, Recovery, and Judgment&quot;">​</a></h1><p>The point of an agent team is not to wait for a central controller to decide every next move. It is to keep advancing work that its members can complete within clear task, role, and authority boundaries. A rail should be a service layer: it tells the team what can be claimed, where facts reside, when dependencies release, and how interrupted execution can recover. It must not replace an agent&#39;s professional judgment or a PM&#39;s or ADMIN&#39;s business decision.</p><p>Multi-agent systems fail in two opposite ways.</p><p>With no rail service, tasks move through chat, two agents start the same work, reports lose their upstream binding, and a process crash leaves nobody able to distinguish retry from stop. Each agent appears free, but the team cannot coordinate reliably.</p><p>With an overpowered rail service, a classifier decides that a plan is “incomplete” and blocks PM dispatch. A temporarily missing artifact becomes a terminal failure. A fixed retry limit silently turns technical backoff into a business decision. The service layer has displaced accountable people and deprived agents of legitimate room to act.</p><p>A sound engineering rail must avoid both extremes: <strong>let agents act autonomously within authorized tasks; automate facts, dispatch, audit, and technical recovery as a service; and reserve hard denial for a closed, reviewable set of mechanical conditions. Scope, acceptance, rework, and final conclusions remain with an accountable agent, PM, or ADMIN.</strong> The CodeFlowMu V1.9.7 candidate is a useful bounded case because that responsibility boundary is the center of its current change.</p><blockquote><p><strong>Series order (3/3).</strong> <a href="./../engineering/2026-08-22-codeflowmu-governance-state-rail">Part 1</a> defines the TMPA–FCoP–CodeFlowMu boundary. <a href="./../engineering/2026-08-22-agent-task-file-state-machine">Part 2</a> tests task identity, lifecycle, dependency, and claim concurrency. This article closes the series by defining the rail&#39;s decision boundary and the governance contract that must bind its implementation.</p></blockquote><h2 id="a-rail-serves-autonomous-collaboration-it-is-neither-the-state-machine-nor-the-pm" tabindex="-1">A rail serves autonomous collaboration; it is neither the state machine nor the PM <a class="header-anchor" href="#a-rail-serves-autonomous-collaboration-it-is-neither-the-state-machine-nor-the-pm" aria-label="Permalink to &quot;A rail serves autonomous collaboration; it is neither the state machine nor the PM&quot;">​</a></h2><p>The file state machine answers where a task is now and how it moved. The rail answers which role receives the work, which session runs, whether a capability is available, when a dependency releases, and how technical execution is recovered.</p><p>The rail is also not a project manager or a manager above the agents. A PM interprets requirements, chooses an execution route, evaluates evidence, and decides whether to accept or rework. An executing agent must likewise plan, implement, and submit evidence within its authorized task and tool boundary. Those judgments contain business or professional meaning. They cannot be derived safely from file presence, elapsed minutes, retry count, or classifier score alone.</p><p>Autonomy is not unconstrained behavior. It is <strong>independent progress within a visible task contract, role capability, current revision, and evidence requirements</strong>. The rail makes those constraints and coordination facts reliable services, so agents do not have to guess whether work is claimed, a dependency is met, or an old session remains valid. It may not inflate that service role into deciding the team&#39;s goal or conclusion.</p><p>NIST&#39;s <a href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10" target="_blank" rel="noreferrer">AI RMF 1.0</a> places governance, defined roles, and human oversight across the AI lifecycle. It does not define an engineering rail, but it offers an independent reference point: automation must operate inside an explicit responsibility structure.</p><h2 id="separate-autonomous-agent-action-from-rail-services" tabindex="-1">Separate autonomous agent action from rail services <a class="header-anchor" href="#separate-autonomous-agent-action-from-rail-services" aria-label="Permalink to &quot;Separate autonomous agent action from rail services&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Typical question</th><th>Correct division of responsibility</th></tr></thead><tbody><tr><td>Fact service</td><td>Does a report exist? What is the current revision?</td><td>The rail records and exposes it; agents use it to continue their work</td></tr><tr><td>Advisory service</td><td>Is evidence probably incomplete? Would another test help?</td><td>The rail explains the concern and suggests an action; an authorized agent or PM decides</td></tr><tr><td>Mechanical wait</td><td>Is an explicit dependency still pending, so that this task is not eligible yet?</td><td>Return <code>waiting_dependency</code>; wait the current operation rather than rejecting it or declaring task failure</td></tr><tr><td>Mechanical denial</td><td>Is identity conflicting, scope unauthorized, task terminal, or execution duplicate?</td><td>Return <code>negative_list_denied</code>, reject the current operation, and preserve evidence; do not close business work</td></tr><tr><td>Business decision</td><td>Should QA be dispatched? Is the result acceptable? Is more rework worth doing?</td><td>Hand the decision to an authorized agent, PM, or ADMIN</td></tr></tbody></table><p><img src="'+a+`" alt="The automation boundary: facts, advice, mechanical denials, and business decisions belong to different actors"></p><p><em>Figure 1. The automation boundary. A mechanical denial applies to the current action; timeout, backoff, and retry must not silently become business conclusions. Source: author synthesis from CodeFlowMu V1.9.7 candidate evidence and NIST AI RMF 1.0.</em></p><p>The dangerous transition is from advisory to mechanical denial. “An attachment is missing” is a fact gap. It becomes a precondition for a specific operation only when the formal task contract or an authorized decision makes it one. Otherwise, the Runtime should report the gap to the PM rather than close the work.</p><h2 id="how-v1-9-7-encodes-the-boundary" tabindex="-1">How V1.9.7 encodes the boundary <a class="header-anchor" href="#how-v1-9-7-encodes-the-boundary" aria-label="Permalink to &quot;How V1.9.7 encodes the boundary&quot;">​</a></h2><p>The CodeFlowMu V1.9.7 rail-assistance contract exposes four dispositions:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> RailAssistanceDisposition</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;neutral&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;unknown_reconcile&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;waiting_dependency&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  |</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;negative_list_denied&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ul><li><code>neutral</code>: facts are available, but the rail issues no allow/deny verdict;</li><li><code>unknown_reconcile</code>: sources are missing or conflicting and require reconciliation;</li><li><code>waiting_dependency</code>: an explicit dependency in the formal TASK is pending, so the current operation waits rather than being denied;</li><li><code>negative_list_denied</code>: a frozen mechanical condition rejects the current operation.</li></ul><p>The result also names <code>decision_owner</code> as AGENT, PM, or ADMIN. The governance snapshot fixes:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">business_decision</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span></span></code></pre></div><p>Together, these details create a testable boundary. The rail can supply facts and command surfaces without smuggling a business verdict into the snapshot.</p><p>The three non-business dispositions are not interchangeable. <code>unknown_reconcile</code> means sources are missing or conflicting and must be reconciled; <code>waiting_dependency</code> means a formal TASK dependency is pending, so the current operation waits; only <code>negative_list_denied</code> means a frozen mechanical condition requires rejection of the current operation. The inspected V1.9.7 contract separates those outcomes. It would therefore be inaccurate to call <code>unknown_reconcile</code> an existing automatic freeze, PM notification, or rollback mechanism, or to call a pending dependency a denial or task failure. If a high-risk downstream operation must stop on conflict, its basis has to be a formal TASK prerequisite, a frozen mechanical rule, or an explicit PM/ADMIN decision; the system may not use a heuristic to select a conflicting branch.</p><p><code>unknown_reconcile</code> also needs one operating contract across the whole series. Source conflicts, a TASK found in two lifecycle stages, and incomplete composite identity are different triggers for the same disposition—not independent recovery systems. An unattended implementation needs a <code>reconcile_owner</code>, trigger reason, canonical task identity and revision, <code>opened_at</code>, a deadline, escalation route, and permitted terminal outcomes. It must not poll a model indefinitely while waiting. The inspected evidence does not yet prove that SLA, notification, circuit breaker, or terminal-transition implementation.</p><p>The excerpts come from the private CodeFlowMu parent implementation at fixed commit <code>2c901972</code>, not from CodeFlowMu Open. This narrow interface contract is shown so readers can inspect the architectural boundary—what the rail may and may not return. It neither opens the full implementation nor constitutes product evidence that the public can reproduce.</p><h2 id="why-mechanical-denials-must-be-closed-and-reviewable" tabindex="-1">Why mechanical denials must be closed and reviewable <a class="header-anchor" href="#why-mechanical-denials-must-be-closed-and-reviewable" aria-label="Permalink to &quot;Why mechanical denials must be closed and reviewable&quot;">​</a></h2><p>The current V1.9.7 contract limits mechanical denial to a closed, reviewable set of conditions:</p><ol><li>an explicit ADMIN or authority decision that denies the current operation;</li><li>an authorization-scope mismatch;</li><li>an inconsistency in the canonical task-identity fields defined by the contract;</li><li>a terminal task state;</li><li>duplicate execution;</li><li>an integrity or safety error.</li></ol><p>These conditions share one property: they can be reviewed from deterministic facts without asking the Runtime to decide whether a plan is intelligent or a result is good enough. Item 3 cannot be hidden behind the vague phrase “real conflict”: a concrete contract must name the compared fields, their canonicalization, and the outcome of a mismatch. Bound task, root-task, thread, and revision fields can, for example, be part of that comparison. Missing fields, an undefined comparison rule, or contradictory facts belong in <code>unknown_reconcile</code>, not in a pretended mechanical denial. The inspected material discloses those command bindings but not a complete composite-identity predicate, so this article does not present one as an exhaustively verified algorithm.</p><p>A source conflict normally enters <code>unknown_reconcile</code> first; it is not automatically inserted into the negative list. Only if it satisfies a deterministic predicate already written into the contract—such as a mismatch in defined identity fields, a scope mismatch, or an explicit decision forbidding the current operation—may the rail turn the <strong>current operation</strong> into <code>negative_list_denied</code>. Otherwise it preserves the conflict and asks an authorized actor to reconcile it.</p><p>An explicit dependency is a different reviewable mechanical condition: it returns <code>waiting_dependency</code>, holding the current operation in a queue until the upstream contract is met. It is not in the frozen negative list and is not a rejection of the task or a business conclusion.</p><p>“Closed” must therefore mean more than a short enum. Every mechanical predicate—including composite identity, dependency authority, and claim contention—must be inspectable inside one versioned policy bundle. Otherwise the list is closed only by name while an opaque predicate or emergency code patch can keep changing who may act.</p><p>As the list grows, business preference tends to disguise itself as infrastructure fact. “The plan has fewer than three steps,” “no ISSUE was filed first,” and “the run exceeded ten minutes” may be useful warnings. None universally implies that the task should stop. A PM or ADMIN may write a condition into a task during creation, revision, or formal approval; they must not turn a new preference into a mechanical block at runtime and thereby create a back door through the service layer. The rail only checks conditions already frozen in the contract or an explicit decision.</p><h2 id="how-governance-enters-the-rail-without-being-rewritten-by-a-patch" tabindex="-1">How governance enters the rail without being rewritten by a patch <a class="header-anchor" href="#how-governance-enters-the-rail-without-being-rewritten-by-a-patch" aria-label="Permalink to &quot;How governance enters the rail without being rewritten by a patch&quot;">​</a></h2><p>TMPA constraints should reach CodeFlowMu through a <strong>versioned governance policy bundle</strong>, not scattered TypeScript branches or an unbounded hot reload. At minimum, the bundle identifies its policy ID, version and digest, supported Runtime range, role and scope predicates, identity canonicalization, dependency-mutation authority, mechanical denial predicates, migration requirements, rollback conditions, and approving actor. Every disposition records the policy version actually used, and that version remains stable for one task round unless an authorized migration creates a new revision.</p><p>This matters most for urgent concurrency fixes. An exclusive reservation, lock file, or compare-and-swap can prevent two physical winners, but it also affects execution authority. Engineering may fail closed—disable competing claimants or contract the deployment back to one Runtime—without changing who is eligible. It may not silently add a new winner-selection or denial rule and explain the governance later. Any authority change must first enter the policy bundle, receive accountable approval, and gain named tests and persisted evidence.</p><p>The same rule applies to dependencies. A running agent may propose an edge change, but only PM, ADMIN, or an explicitly delegated actor may mutate the graph. The accepted change creates a new task revision and reruns identity, scope, and cycle checks before execution continues.</p><h2 id="what-the-rail-should-automate" tabindex="-1">What the rail should automate <a class="header-anchor" href="#what-the-rail-should-automate" aria-label="Permalink to &quot;What the rail should automate&quot;">​</a></h2><h3 id="bind-identity-and-scope" tabindex="-1">Bind identity and scope <a class="header-anchor" href="#bind-identity-and-scope" aria-label="Permalink to &quot;Bind identity and scope&quot;">​</a></h3><p>A task command should bind task, root, thread, round, and revision. Commands against a stale revision, capabilities mounted for another task, or different business intents sharing one idempotency key should be rejected before effect.</p><h3 id="enforce-role-tool-capability" tabindex="-1">Enforce role/tool capability <a class="header-anchor" href="#enforce-role-tool-capability" aria-label="Permalink to &quot;Enforce role/tool capability&quot;">​</a></h3><p>Development, QA, operations, and review roles should not share one mutable tool surface. V1.9.7 checks canonical tool identity and active capability. On the inspected PM task-mutation path, requests enter the shared TaskCommandKernel, so identity, scope, and duplicate-prevention checks execute on that path. That evidence does not exhaust every legacy or alternative endpoint. Proving that no bypass exists would also require an endpoint inventory, static scans, and rejection tests for bypass paths.</p><p>This is tool admission, not complete effect analysis. Path escape, command parameters, and operating-system privileges still require lower-level policy and sandbox controls.</p><p>Tool admission should not depend on a static role alone. An engineering design should apply a separate operation policy to lifecycle stage, current revision, and action target: once a task is in <code>review</code> or a terminal state, a request by the executor to keep writing code should be rechecked for a still-explicit, valid rework or execution entry point. The inspected V1.9.7 evidence proves canonical tool ID, active capability, task scope, and revision checks; it does not prove that every tool has unified dynamic contraction across <code>active</code>, <code>review</code>, and <code>done</code>. This is a policy and test to add, not a feature this article claims is complete.</p><h3 id="queue-and-release-explicit-dependencies" tabindex="-1">Queue and release explicit dependencies <a class="header-anchor" href="#queue-and-release-explicit-dependencies" aria-label="Permalink to &quot;Queue and release explicit dependencies&quot;">​</a></h3><p>When a QA task explicitly depends on a DEV child, the rail may keep QA waiting until the upstream contract is satisfied. The hold comes from a reviewable TASK edge, not a classifier&#39;s interpretation of prose.</p><p>Consider the contrast. If QA starts simply because it sees an old-round DEV report, it can treat a previous output as input to the current task. A sound contract binds the QA task to a specific upstream task and its current revision; before that dependency is satisfied, it returns <code>waiting_dependency</code> rather than launching QA. Only when completion evidence matches the bound version does the rail release the edge. This is a design example of a reviewable dependency; it is not a claim that V1.9.7 has tests for every report–revision matching combination.</p><h3 id="preserve-technical-facts-for-long-jobs" tabindex="-1">Preserve technical facts for long jobs <a class="header-anchor" href="#preserve-technical-facts-for-long-jobs" aria-label="Permalink to &quot;Preserve technical facts for long jobs&quot;">​</a></h3><p>Work that must outlive a session, survive Runtime restart, expose continuous logs, or support precise cancellation can use the optional managed-command service. V1.9.7 also states that short tests and builds may use native host command tools. The absence of managed-command tools must not be treated as proof that an agent cannot work or submit a REPORT.</p><h3 id="wake-and-recover-without-declaring-a-business-outcome" tabindex="-1">Wake and recover without declaring a business outcome <a class="header-anchor" href="#wake-and-recover-without-declaring-a-business-outcome" aria-label="Permalink to &quot;Wake and recover without declaring a business outcome&quot;">​</a></h3><p>The rail may wake an eligible agent, restore a recoverable session, retry a deterministic technical step, and add cooldown or audit after repeated failures. Counts and time windows are useful for throttling and operator attention. They should not silently become permanent business blocks.</p><p>A good recovery result says what was observed, what was repaired mechanically, what remains unknown, and who should decide next. It does not announce project failure on behalf of the PM.</p><p>Timeout must also be treated as a technical fact, not a business verdict. V1.9.7&#39;s optional managed-command service can retain long-job state, continuous logs, bounded waits, and precisely authorized cancellation. That supports recording that a session or tool call exceeded its expected window; it does not prove that every session already has a heartbeat, automatic diagnosis, or PM notification. A sound follow-on policy records timeout in session or job evidence, exposes retry, takeover, or termination choices to the decision owner, and avoids silently promoting technical timeout into Task Failure.</p><h2 id="a-three-second-boundary-test" tabindex="-1">A three-second boundary test <a class="header-anchor" href="#a-three-second-boundary-test" aria-label="Permalink to &quot;A three-second boundary test&quot;">​</a></h2><p>Suppose a QA REPORT arrives without the raw compatibility log named in the task.</p><p>An overreaching implementation does this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Runtime sees missing attachment</span></span>
<span class="line"><span>→ marks the root task failed</span></span>
<span class="line"><span>→ permanently blocks PM consolidation</span></span></code></pre></div><p>A bounded implementation distinguishes two cases:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>If the formal TASK, at creation, revision, or formal approval, has already written “this log is required for acceptance” as a frozen deterministic prerequisite:</span></span>
<span class="line"><span>→ record the evidence gap and reject this acceptance attempt</span></span>
<span class="line"><span>→ PM decides whether to retest, rework, or change the contract</span></span>
<span class="line"><span></span></span>
<span class="line"><span>If the log is only a classifier recommendation:</span></span>
<span class="line"><span>→ expose the gap and the recommendation</span></span>
<span class="line"><span>→ PM decides based on risk and available evidence</span></span></code></pre></div><p>The first branch is a contract-design illustration, not a claim that V1.9.7 automatically turns every missing attachment into a denial. If the current interface has no pre-frozen predicate, the correct behavior remains to record the evidence gap and hand the decision to PM.</p><h2 id="what-v1-9-7-actually-verified" tabindex="-1">What V1.9.7 actually verified <a class="header-anchor" href="#what-v1-9-7-actually-verified" aria-label="Permalink to &quot;What V1.9.7 actually verified&quot;">​</a></h2><p>The first-party candidate packet <code>V1.9.7-RAIL-ASSISTANCE-RC-20260822-001</code> for candidate code <code>9e4c6e6a</code> records the following. The packet distinguishes parent-source checks, candidate-code regression, and controlled restart loading; it should not be compressed into a claim that every result came from one identical evidence node:</p><ul><li>10 consecutive passes of the fixed critical scenarios, with Runtime at 115/115 in each round;</li><li>Runtime full regression at 1706/1706;</li><li>Shell full regression at 936/936;</li><li>passing Runtime typecheck, Shell production build, REPORT identity, and version-consistency checks;</li><li>a controlled restart after which the process loaded V1.9.7, reported <code>health=ok</code>, and retained an online gateway, ownership of the single-writer lock by the current process, and a consistent project-root binding.</li></ul><p>These figures are totals from test sets at different levels. They cannot be added together or read as equal coverage of all four rail-assistance dispositions. The available packet does not record the number of direct cases for <code>neutral</code>, <code>unknown_reconcile</code>, <code>waiting_dependency</code>, and <code>negative_list_denied</code>; this article therefore does not use 115, 1706, or 936 to claim complete validation of those boundaries. The next evidence packet should list named cases, expected dispositions, and observed results for each state.</p><p>That next packet should be a traceable matrix rather than another aggregate total: <strong>governance claim → policy predicate and version → CodeFlowMu entry point → named positive and negative test → persisted result and commit</strong>. It should separately cover unauthorized dependency mutation, stale policy or task revision, same-TASK concurrent claim with exactly one executable credential and zero loser side effects, each of the four dispositions, reconciliation timeout and escalation, and authorized recovery. Only that matrix can show that governance semantics and engineering behavior moved together.</p><p>This article does not use CodeFlowMu Open source or Open-edition test counts as product evidence.</p><p>The numbers support only the tested paths on the recorded Windows workstation, candidate code, and fixed test set. Parent-source checks, code regression, and restart loading are separate evidence nodes in the packet. They are not penetration testing, independent reproduction, formal verification, or a cross-platform reliability claim. The packet also preserves failures discovered in earlier change checks instead of overwriting them with final-release checks.</p><p>Version status requires the same care. The version files and live process report V1.9.7, while the release note still calls it a candidate and reserves final <code>RELEASED</code> authority for ADMIN. The rail should not release on behalf of ADMIN, and an article should not rewrite that boundary either.</p><h2 id="residual-risks" tabindex="-1">Residual risks <a class="header-anchor" href="#residual-risks" aria-label="Permalink to &quot;Residual risks&quot;">​</a></h2><p>First, the frozen negative list is an engineering contract, not a complete threat model. Prompt injection, parameter escape, supply-chain risk, and external effects still require deeper security controls.</p><p>Second, one canonical fact kernel does not prove that every legacy endpoint consumes it. Regression tests and static scans reduce the risk of old adjudication paths returning; they cannot prevent future parallel classifiers from being introduced.</p><p>Third, technical recovery does not validate a business result. Restoring a process, recovering logs, or redelivering a REPORT does not replace content review or ADMIN judgment for high-impact action.</p><p>Fourth, the evidence is first-party. Stronger conclusions require independent reproduction, more crash points, multiple host and filesystem environments, and observation of real long-running teams.</p><h2 id="audit-your-own-rail" tabindex="-1">Audit your own rail <a class="header-anchor" href="#audit-your-own-rail" aria-label="Permalink to &quot;Audit your own rail&quot;">​</a></h2><p>For each automation rule, answer:</p><ol><li>What source produces the fact?</li><li>When evidence is missing, does the system say “unknown” or guess?</li><li>Is the output advice, or does it stop an operation?</li><li>If it stops, is the reason on a short frozen mechanical list?</li><li>Does it stop only the current operation, or does it close the business task?</li><li>Who owns the final decision, and is that decision bound to the current revision?</li><li>Do retry, cooldown, timeout, and recovery change only technical state rather than silently decide a business outcome?</li><li>Is there a test proving that classifier scores, elapsed time, and artifact gaps cannot silently become business verdicts?</li></ol><p>The value of a rail is not that it decides everything for agents. It lets each agent work more autonomously within the right boundary while giving the team stable facts, controlled motion, and recoverable execution. <strong>The more reliable the rail becomes, the clearer both agent autonomy and the ownership of business judgment should be.</strong></p><h2 id="sources-and-evidence-boundaries" tabindex="-1">Sources and evidence boundaries <a class="header-anchor" href="#sources-and-evidence-boundaries" aria-label="Permalink to &quot;Sources and evidence boundaries&quot;">​</a></h2><p>For how this series distinguishes public specifications, private code excerpts, first-party execution records, and independent material, see <a href="./../methodology/evidence-boundaries">How to Read Engineering Evidence at the Digital Employee Works</a>. The sources below still support only the specific claims stated in this article.</p><ul><li><a href="https://www.nist.gov/publications/artificial-intelligence-risk-management-framework-ai-rmf-10" target="_blank" rel="noreferrer">NIST AI RMF 1.0</a> supports the general context of governance, accountable roles, and human oversight across an AI lifecycle. It neither defines an engineering rail nor certifies CodeFlowMu.</li><li><a href="https://cheatsheetseries.owasp.org/cheatsheets/AI_Agent_Security_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP AI Agent Security Cheat Sheet</a> supports the general security need for explicit authorization, least privilege, and isolation around agent tool calls. It does not prove that every tool policy here is complete.</li><li><a href="https://www.w3.org/TR/prov-o/" target="_blank" rel="noreferrer">W3C PROV-O</a> is an independent provenance-modeling reference for separating facts, activities, and responsible agents. It does not prescribe this article&#39;s business-decision or recovery policy.</li><li>V1.9.7 figures, interface excerpts, and controlled-restart observations are first-party candidate evidence, limited to the tested paths named here. They are not penetration testing, third-party reproduction, or cross-platform conclusions. Accessed 2026-08-23.</li></ul>`,82))])}const v=i(l,[["render",d]]);export{b as __pageData,v as default};
